const requested = $('Execute Workflow Trigger').first().json.items || [];
const inventory = $input.all().map(e => e.json).filter(r => r.item_name);

const norm = (s) => String(s ?? '')
  .replace(/[\u064B-\u065F\u0670\u0640]/g, '')
  .replace(/[أإآ]/g, 'ا')
  .replace(/ى/g, 'ي')
  .replace(/ة/g, 'ه')
  .replace(/\s+/g, ' ')
  .trim()
  .toLowerCase();

const findRow = (name) => {
  const key = norm(name);
  if (!key) return { row: null, candidates: [] };
  const exact = inventory.filter(r => norm(r.item_name) === key);
  if (exact.length === 1) return { row: exact[0], candidates: [] };
  const pool = exact.length ? exact : inventory.filter(r => {
    const n = norm(r.item_name);
    return n && (n.includes(key) || key.includes(n));
  });
  if (pool.length === 1) return { row: pool[0], candidates: [] };
  return { row: null, candidates: pool.map(r => String(r.item_name).trim()) };
};

const wanted = new Map();
const unmatched_items = [];

for (const req of requested) {
  const qty = Number(req.quantity ?? req.qty);
  if (!Number.isFinite(qty) || qty <= 0) {
    unmatched_items.push({ name: req.name, reason: 'invalid_quantity', candidates: [] });
    continue;
  }
  const { row, candidates } = findRow(req.name);
  if (!row) {
    unmatched_items.push({ name: req.name, reason: candidates.length ? 'ambiguous' : 'not_found', candidates });
    continue;
  }
  const entry = wanted.get(row.row_number) || { row, qty: 0 };
  entry.qty += qty;
  wanted.set(row.row_number, entry);
}

const full_check = [...wanted.values()].map(({ row, qty }) => {
  const stock = Number(row.quantity_available);
  const availableQty = Number.isFinite(stock) ? stock : 0;
  return {
    name: String(row.item_name).trim(),
    requested_qty: qty,
    available_qty: availableQty,
    sufficient: availableQty >= qty,
    row_number: row.row_number
  };
});

const confirmed_items = full_check.filter(r => r.sufficient);
const unavailable_items = full_check.filter(r => !r.sufficient);

return [{
  json: {
    all_available: unavailable_items.length === 0 && unmatched_items.length === 0,
    confirmed_items,
    unavailable_items,
    unmatched_items,
    full_check
  }
}];
